-- Continues the canonical website submission and owner-approved booking fixture.
-- No job statuses, invoice totals or payment records are manufactured directly.
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select public.publish_hourly_quote('20000000-0000-4000-8000-000000000001',(select id from public.service_requests),(select revision from public.service_requests),'Synthetic agreed leaf management scope',120,false,false,null,'lifecycle-price-01');
select public.approve_quote('20000000-0000-4000-8000-000000000001',(select id from public.quotes),1,'Synthetic customer agreement for isolated local test');
select public.job_action('20000000-0000-4000-8000-000000000001',(select id from public.jobs),1,'start','Synthetic work starts','lifecycle-start-01');
select public.job_action('20000000-0000-4000-8000-000000000001',(select id from public.jobs),1,'start','Synthetic work starts','lifecycle-start-01');
select public.job_action('20000000-0000-4000-8000-000000000001',(select id from public.jobs),2,'pause','','lifecycle-pause-01');
select public.job_action('20000000-0000-4000-8000-000000000001',(select id from public.jobs),3,'resume','','lifecycle-resume-01');
select public.save_invoice_labor('20000000-0000-4000-8000-000000000001',(select id from public.jobs),4,'[{"description":"Synthetic recorded leaf management","recordedMinutes":120,"chargedCents":12000,"waiverReason":""}]','lifecycle-draft-01');
select public.complete_service_call('20000000-0000-4000-8000-000000000001',(select id from public.jobs),5,'lifecycle-complete-01');
select pg_temp.assert_true((select count(*)=0 from public.invoices),'completion does not silently issue invoice');
select pg_temp.assert_true((select count(*)=0 from public.work_sessions where ended_at is null),'completion immediately stops work timers before invoice review');
select public.approve_invoice('20000000-0000-4000-8000-000000000001',(select id from public.jobs),6,12000,true,'lifecycle-invoice-01');
select public.approve_invoice('20000000-0000-4000-8000-000000000001',(select id from public.jobs),6,12000,true,'lifecycle-invoice-01');
select pg_temp.assert_true((select count(*)=1 from public.invoices),'one issued invoice after retried owner review');
reset role;
update public.organizations set status='active';
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
-- Local simulated setup; no provider requests or external messages.
select public.activate_central_mail('20000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','https://website.example.invalid','notifications@example.invalid');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select public.request_invoice_delivery('20000000-0000-4000-8000-000000000001',(select id from public.invoices),true,'lifecycle-mail-key-01');
select public.request_invoice_delivery('20000000-0000-4000-8000-000000000001',(select id from public.invoices),true,'lifecycle-mail-key-02');
select pg_temp.assert_true((select count(*)=1 from public.outbox where kind='invoice.delivery'),'one logical invoice email across repeated send clicks');
select public.record_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),5000,'cash','Synthetic partial cash receipt',now(),true,'lifecycle-cash-key-01');
select public.record_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),5000,'cash','Synthetic partial cash receipt',now(),true,'lifecycle-cash-key-01');
select pg_temp.assert_true((select total_cents-(select sum(cents) from public.payments)=7000 from public.invoices),'partial cash retry leaves exactly seventy dollars due');
select pg_temp.assert_true((select count(*)=0 from public.outbox where kind='invoice.paid'),'partial receipt does not send fully-paid message');
select public.record_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),7000,'zelle','Synthetic actual Zelle receipt',now(),true,'lifecycle-zelle-key-01');
select public.record_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),7000,'zelle','Synthetic actual Zelle receipt',now(),true,'lifecycle-zelle-key-01');
reset role;
select pg_temp.assert_true((select count(*)=2 and sum(cents)=12000 from public.payments),'one cash and one Zelle receipt settle exact issued total');
select pg_temp.assert_true((select count(*)=1 from public.outbox where kind='invoice.paid'),'one paid milestone after full settlement');
select pg_temp.assert_true((select sum(debit_cents::bigint-credit_cents)=0 from public.journal_lines),'full service workflow ledger balances');
select pg_temp.assert_true((select count(*)=1 from public.service_requests),'customer request retained through payment');
select pg_temp.assert_true((select count(*)=1 from public.appointments where status='reserved'),'confirmed appointment retained through payment');
select pg_temp.assert_true((select count(*)=0 from public.work_sessions where ended_at is null),'completed work has no running timer');

-- Mistaken receipt correction retains the original and appends a balanced opposite.
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select public.reverse_recorded_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),(select id from public.payments where method='cash'),'Synthetic mistaken receipt correction','lifecycle-correction-01');
select public.reverse_recorded_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),(select id from public.payments where method='cash'),'Synthetic mistaken receipt correction','lifecycle-correction-01');
select pg_temp.assert_true((select count(*)=3 and sum(cents)=7000 from public.payments),'correction replay appends exactly one opposite receipt');
select pg_temp.assert_true((select cents=5000 and reference='Synthetic partial cash receipt' from public.payments where method='cash'),'original receipt retained unchanged');
do $$begin begin perform public.reverse_recorded_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),(select id from public.payments where method='cash'),'Different synthetic correction reason','lifecycle-correction-01');raise exception 'TEST FAILED changed replay';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;end$$;
do $$begin begin perform public.reverse_recorded_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),(select id from public.payments where method='cash'),'Synthetic second correction attempt','lifecycle-correction-02');raise exception 'TEST FAILED double correction';exception when others then if sqlerrm<>'PAYMENT_ALREADY_REVERSED' then raise;end if;end;end$$;
reset role;
select pg_temp.assert_true((select status='suppressed' from public.outbox where kind='invoice.paid'),'unsent paid notice suppressed when balance reopens');
select pg_temp.assert_true((select sum(debit_cents::bigint-credit_cents)=0 from public.journal_lines),'corrected ledger balances');
set local role authenticated;
select public.record_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),5000,'cash','Synthetic corrected receipt',now(),true,'lifecycle-new-payment-01');
reset role;
select pg_temp.assert_true((select count(*)=1 and bool_and(status='pending') from public.outbox where kind='invoice.paid'),'same definitely suppressed paid notice requeues without duplicate');
update public.outbox set status='accepted' where kind='invoice.paid';
set local role authenticated;
select public.reverse_recorded_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),(select id from public.payments where method='zelle'),'Synthetic mistaken Zelle correction','lifecycle-correction-03');
select public.record_payment('20000000-0000-4000-8000-000000000001',(select id from public.invoices),7000,'zelle','Synthetic corrected Zelle receipt',now(),true,'lifecycle-new-payment-02');
reset role;
select pg_temp.assert_true((select count(*)=1 and bool_and(status='accepted') from public.outbox where kind='invoice.paid'),'already accepted paid milestone never resent');
select pg_temp.assert_true((select sum(cents)=12000 from public.payments),'corrected receipts settle exact invoice amount');
select pg_temp.assert_true((select sum(debit_cents::bigint-credit_cents)=0 from public.journal_lines),'all correction journals remain balanced');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
do $$begin begin perform public.reverse_recorded_payment('20000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000001','80000000-0000-4000-8000-000000000002','Synthetic forbidden correction','lifecycle-denied-correction');raise exception 'TEST FAILED cross tenant';exception when insufficient_privilege then null;end;end$$;
reset role;

set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select pg_temp.assert_true(jsonb_array_length(public.accounting_journal_export('20000000-0000-4000-8000-000000000001',current_date-1,current_date+1)->'rows')=(select count(*) from public.journal_lines),'journal export contains all original/correcting transaction lines');
select pg_temp.assert_true((public.accounting_journal_export('20000000-0000-4000-8000-000000000001',current_date-1,current_date+1)->>'complete')::boolean,'journal export explicitly complete');
reset role;
with entries as (insert into public.journal_entries(organization_id,source_kind,source_id) select '20000000-0000-4000-8000-000000000001','expense',gen_random_uuid() from generate_series(1,5001) returning organization_id,id)
insert into public.journal_lines(organization_id,entry_id,account,debit_cents,credit_cents) select e.organization_id,e.id,case when side=0 then 'cash' else 'expenses' end,case when side=0 then 1 else 0 end,case when side=0 then 0 else 1 end from entries e cross join generate_series(0,1) side;
set local role authenticated;
do $$begin begin perform public.accounting_journal_export('20000000-0000-4000-8000-000000000001',current_date-1,current_date+1);raise exception 'TEST FAILED partial oversized export';exception when others then if sqlerrm<>'EXPORT_RANGE_TOO_LARGE' then raise;end if;end;end$$;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000002","session_id":"10000000-0000-4000-8000-000000000002","aal":"aal1"}',true);
do $$begin begin perform public.accounting_journal_export('20000000-0000-4000-8000-000000000001',current_date-1,current_date+1);raise exception 'TEST FAILED cross-tenant journal';exception when insufficient_privilege then null;end;end$$;
reset role;
-- Isolated file metadata fixture: byte attestation is covered in private-customer-files.sql.
reset role;
insert into private.customer_supporting_files(organization_id,id,customer_id,actor_id,request_key,purpose,original_name,mime,bytes,sha256,object_path,status)
select organization_id,'83000000-0000-4000-8000-000000000001',customer_id,'00000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000002','receipt','synthetic.png','image/png',12,repeat('a',64),organization_id::text||'/83000000-0000-4000-8000-000000000001','ready' from public.jobs limit 1;
insert into public.customers(organization_id,id,display_name) values('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000003','Synthetic unrelated customer');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"00000000-0000-4000-8000-000000000001","session_id":"10000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',0,'job',(select id from public.jobs),'Synthetic photo associated with original job',true,'83000000-0000-4000-8000-000000000004');
select public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',0,'job',(select id from public.jobs),'Synthetic photo associated with original job',true,'83000000-0000-4000-8000-000000000004');
do $$begin begin perform public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',0,'job',(select id from public.jobs),'Synthetic changed reason must fail',true,'83000000-0000-4000-8000-000000000004');raise exception 'TEST FAILED changed link replay';exception when others then if sqlerrm<>'IDEMPOTENCY_CONFLICT' then raise;end if;end;end$$;
do $$begin begin perform public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',0,'invoice',(select id from public.invoices),'Synthetic stale version must fail',true,'83000000-0000-4000-8000-000000000005');raise exception 'TEST FAILED stale link';exception when others then if sqlerrm<>'STALE_REVISION' then raise;end if;end;end$$;
do $$begin begin perform public.link_customer_file('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000003','83000000-0000-4000-8000-000000000001',1,'job',(select id from public.jobs),'Synthetic different customer must fail',true,'83000000-0000-4000-8000-000000000006');raise exception 'TEST FAILED wrong customer';exception when insufficient_privilege then null;end;end$$;
select public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',1,'invoice',(select id from public.invoices),'Synthetic corrected association to issued invoice',true,'83000000-0000-4000-8000-000000000007');
select pg_temp.assert_true(jsonb_array_length(public.customer_file_workspace('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001')->'events')=2,'original link retained with one correction');
select pg_temp.assert_true((public.customer_file_workspace('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs))->'files'->0->'link'->>'kind')='invoice','latest corrected link listed');
select pg_temp.assert_true(jsonb_array_length(public.customer_file_targets('20000000-0000-4000-8000-000000000001','83000000-0000-4000-8000-000000000003','job')->'rows')=0,'unrelated customer has no job targets');
select public.record_business_expense('20000000-0000-4000-8000-000000000001',current_date,'Synthetic Vendor','supplies','Synthetic receipt association',600,'cash','synthetic-receipt',true,'file-link-synthetic-expense');
select public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',2,'expense',(select id from public.business_expenses limit 1),'Synthetic reviewed company receipt association',true,'83000000-0000-4000-8000-000000000008');
select pg_temp.assert_true(jsonb_array_length(public.customer_file_targets('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'expense','Synthetic Vendor')->'rows')=1,'bounded expense search returns recorded expense');
select public.link_customer_file('20000000-0000-4000-8000-000000000001',(select customer_id from public.jobs),'83000000-0000-4000-8000-000000000001',3,'customer',(select customer_id from public.jobs),'Synthetic correction to customer record only',true,'83000000-0000-4000-8000-000000000009');
reset role;
select pg_temp.assert_true((select count(*)=4 from private.customer_file_links),'four append-only link events; exact replay adds none');
select pg_temp.assert_true((select count(*)=4 from public.audit_events where action='customer.file_linked'),'one audit per confirmed association');
select pg_temp.assert_true((select bytes=12 and sha256=repeat('a',64) from private.customer_supporting_files),'link corrections retain frozen byte evidence');
do $$begin begin delete from private.customer_file_links;raise exception 'TEST FAILED link history deletion';exception when others then if sqlerrm='TEST FAILED link history deletion' then raise;end if;end;end$$;
